    16→  const createPlan = useProjectConfigStore((s) => s.createPlan);
    17→  const updatePlan = useProjectConfigStore((s) => s.updatePlan);
    18→  const deletePlan = useProjectConfigStore((s) => s.deletePlan);
    19→
    20→  const [selectedPlan, setSelectedPlan] = useState<ProjectPlan | null>(null);
    21→  const [editing, setEditing] = useState(false);
    22→  const [editContent, setEditContent] = useState("");
    23→  const [creating, setCreating] = useState(false);
    24→  const [newPlanForm, setNewPlanForm] = useState<NewPlanForm>({
